from collections import Counter
from operator import itemgetter
import itertools

def task_func(word_dict):
    if not word_dict:
        return {}

    words = (
        str(word)
        for word in word_dict.keys()
        if isinstance(word, str) or word is not None
    )

    letters = itertools.chain.from_iterable(
        ch for ch in word if ch.isalpha()
        for word in words
    )

    return dict(Counter(letters))
